# ---------------------------------------------------------------------------
# Custom Exceptions
# ---------------------------------------------------------------------------
class ValidationError(Exception):
    """Base exception for validation failures."""
    pass

class SchemaMismatchError(ValidationError):
    """Raised when input does not conform to the expected schema."""
    def __init__(self, field: str, expected: Any, received: Any):
        self.field = field
        self.expected = expected
        self.received = received
        super().__init__(f"Field '{field}': expected {expected}, got {received}")

class TypeConstraintError(ValidationError):
    """Raised when a type constraint is violated."""
    pass

class RangeConstraintError(ValidationError):
    """Raised when a numeric range constraint is violated."""
    pass

class PatternMismatchError(ValidationError):
    """Raised when a regex pattern does not match."""
    pass

class RequiredFieldMissingError(ValidationError):
    """Raised when a required field is absent."""
    def __init__(self, field: str):
        self.field = field
        super().__init__(f"Required field '{field}' is missing")

# ---------------------------------------------------------------------------
# Enums & Constants
# ---------------------------------------------------------------------------
class ValidationLevel(Enum):
    STRICT = "strict"
    MODERATE = "moderate"
    PERMISSIVE = "permissive"

class DataType(Enum):
    STRING = "string"
    INTEGER = "integer"
    FLOAT = "float"
    BOOLEAN = "boolean"
    LIST = "list"
    DICT = "dict"
    ANY = "any"

