@dataclass
class ValidationResult:
    """Encapsulates the outcome of a validation operation."""
    is_valid: bool
    errors: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)
    sanitized_data: Optional[Any] = None
    timestamp: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    def merge(self, other: 'ValidationResult') -> 'ValidationResult':
        """Merge two validation results."""
        return ValidationResult(
            is_valid=self.is_valid and other.is_valid,
            errors=self.errors + other.errors,
            warnings=self.warnings + other.warnings,
            sanitized_data=other.sanitized_data if other.sanitized_data is not None else self.sanitized_data,
            timestamp=datetime.now(timezone.utc).isoformat()
        )

    def to_dict(self) -> Dict[str, Any]:
        """Serialize to dictionary for logging/telemetry."""
        return asdict(self)

@dataclass
class FieldConstraint:
    """Defines constraints for a single field."""
    field_name: str
    required: bool = True
    data_type: DataType = DataType.STRING
    min_length: Optional[int] = None
    max_length: Optional[int] = None
    min_value: Optional[Union[int, float]] = None
    max_value: Optional[Union[int, float]] = None
    regex_pattern: Optional[str] = None
    allowed_values: Optional[List[Any]] = None
    custom_validator: Optional[Callable[[Any], bool]] = None
    sanitizer: Optional[Callable[[Any], Any]] = None
    nested_schema: Optional[Dict[str, 'FieldConstraint']] = None

    def validate(self, value: Any) -> ValidationResult:
        """Validate a single value against this constraint."""
        errors = []
        warnings = []
        sanitized = value

        # 1. Type check
        if self.data_type != DataType.ANY:
            type_map = {
                DataType.STRING: str,
                DataType.INTEGER: int,
                DataType.FLOAT: float,
                DataType.BOOLEAN: bool,
                DataType.LIST: list,
                DataType.DICT: dict,
            }
            expected_type = type_map.get(self.data_type)
            if expected_type and not isinstance(value, expected_type):
                errors.append(f"Type mismatch for '{self.field_name}': expected {self.data_type.value}, got {type(value).__name__}")
                return ValidationResult(is_valid=False, errors=errors)

        # 2. Length constraints (strings/lists)
        if self.min_length is not None and hasattr(value, '__len__'):
            if len(value) < self.min_length:
                errors.append(f"'{self.field_name}' length {len(value)} < minimum {self.min_length}")
        if self.max_length is not None and hasattr(value, '__len__'):
            if len(value) > self.max_length:
                errors.append(f"'{self.field_name}' length {len(value)} > maximum {self.max_length}")

        # 3. Numeric range constraints
        if isinstance(value, (int, float)):
            if self.min_value is not None and value < self.min_value:
                errors.append(f"'{self.field_name}' value {value} < minimum {self.min_value}")
            if self.max_value is not None and value > self.max_value:
                errors.append(f"'{self.field_name}' value {value} > maximum {self.max_value}")

        # 4. Regex pattern
        if self.regex_pattern and isinstance(value, str):
            if not re.match(self.regex_pattern, value):
                errors.append(f"'{self.field_name}' does not match pattern {self.regex_pattern}")

        # 5. Allowed values
        if self.allowed_values is not None and value not in self.allowed_values:
            errors.append(f"'{self.field_name}' value '{value}' not in allowed set: {self.allowed_values}")

        # 6. Custom validator
        if self.custom_validator and not self.custom_validator(value):
            errors.append(f"'{self.field_name}' failed custom validation")

        # 7. Sanitization
        if self.sanitizer:
            try:
                sanitized = self.sanitizer(value)
            except Exception as e:
                errors.append(f"Sanitization failed for '{self.field_name}': {e}")

        return ValidationResult(
            is_valid=len(errors) == 0,
            errors=errors,
            warnings=warnings,
            sanitized_data=sanitized
        )

# ---------------------------------------------------------------------------
# Schema Definition
# ---------------------------------------------------------------------------
class ValidationSchema:
    """Defines the expected structure and constraints for an input payload."""

    def __init__(self, fields: Dict[str, FieldConstraint], level: ValidationLevel = ValidationLevel.STRICT):
        self.fields = fields
        self.level = level

    def validate(self, data: Dict[str, Any]) -> ValidationResult:
        """Validate an entire data dictionary against this schema."""
        result = ValidationResult(is_valid=True)

        # Check for required fields
        for field_name, constraint in self.fields.items():
            if constraint.required and field_name not in data:
                if self.level == ValidationLevel.STRICT:
                    result.errors.append(f"Required field '{field_name}' is missing")
                    result.is_valid = False
                elif self.level == ValidationLevel.MODERATE:
                    result.warnings.append(f"Required field '{field_name}' is missing")
                # PERMISSIVE: silently ignore

        # Validate present fields
        for field_name, value in data.items():
            constraint = self.fields.get(field_name)
            if constraint:
                field_result = constraint.validate(value)
                result = result.merge(field_result)
            else:
                if self.level == ValidationLevel.STRICT:
                    result.errors.append(f"Unexpected field '{field_name}'")
                    result.is_valid = False
                elif self.level == ValidationLevel.MODERATE:
                    result.warnings.append(f"Unexpected field '{field_name}'")

        return result

