def create_default_schema() -> ValidationSchema:
    """Factory function to create a default validation schema for generic inputs."""
    return ValidationSchema({
        "id": FieldConstraint("id", required=True, data_type=DataType.STRING, min_length=8, max_length=64, regex_pattern=r"^[a-zA-Z0-9_-]+$"),
        "name": FieldConstraint("name", required=True, data_type=DataType.STRING, min_length=1, max_length=256),
        "version": FieldConstraint("version", required=False, data_type=DataType.STRING, regex_pattern=r"^\d+\.\d+\.\d+$"),
        "metadata": FieldConstraint("metadata", required=False, data_type=DataType.DICT),
        "tags": FieldConstraint("tags", required=False, data_type=DataType.LIST),
    })

def sanitize_html(input_str: str) -> str:
    """Sanitize a string by escaping HTML special characters."""
    html_escape_table = {
        "&": "&amp;",
        '"': "&quot;",
        "'": "&apos;",
        ">": "&gt;",
        "<": "&lt;",
    }
    return "".join(html_escape_table.get(c, c) for c in input_str)

